import sys
import ast

# Target file containing potential tainted SQL string construction
source_file = "/src/app/app.py"

def is_tainted_sql(binop_node):
    """
    Detect patterns like:
        "SELECT ... %s" % content['search']
    """
    # Ensure the operator is the string formatting modulo operator
    if not isinstance(binop_node.op, ast.Mod):
        return False

    # Left side should be a string constant containing SQL keywords
    left = binop_node.left
    if isinstance(left, ast.Constant) and isinstance(left.value, str):
        sql_keywords = ["select", "insert", "update", "delete", "where"]
        if not any(kw in left.value.lower() for kw in sql_keywords):
            return False
    else:
        return False

    # Right side should be a subscript reading from a request-derived dict (e.g., content['search'])
    right = binop_node.right
    if isinstance(right, ast.Subscript):
        # Verify the base is a Name like 'content' or an attribute chain ending in 'json'
        base = right.value
        if isinstance(base, ast.Name) and base.id in {"content", "data", "params", "request"}:
            return True
        if isinstance(base, ast.Attribute):
            # e.g., request.json['url']
            # Walk attribute chain to see if it ends with 'json'
            while isinstance(base, ast.Attribute):
                if base.attr == "json":
                    return True
                base = base.value
    return False

def check_file_for_tainted_sql(filepath):
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            tree = ast.parse(f.read(), filename=filepath)
    except Exception:
        return False

    for node in ast.walk(tree):
        # Look for assignments where the value is a BinOp with Mod (%)
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.BinOp):
            if is_tainted_sql(node.value):
                return True
        # Also catch direct usage without assignment (e.g., passed directly to execute)
        if isinstance(node, ast.Call):
            # Detect db.engine.execute("...%s" % content['...'])
            for arg in node.args:
                if isinstance(arg, ast.BinOp) and is_tainted_sql(arg):
                    return True
    return False

if check_file_for_tainted_sql(source_file):
    print("VALIDATION_SUCCESS: Detected unsafe string formatting for SQL query.")
    sys.exit(0)
else:
    sys.exit(1)

import sys
import ast

SOURCE_FILE = "/src/app/app.py"
SQL_KEYWORDS = {"SELECT", "INSERT", "UPDATE", "DELETE"}


def is_sql_string(node):
    """Return True if the string node looks like an SQL statement."""
    if isinstance(node, ast.Str):          # Python <3.8
        txt = node.s
    elif isinstance(node, ast.Constant) and isinstance(node.value, str):  # Python >=3.8
        txt = node.value
    else:
        return False
    return any(kw in txt.upper() for kw in SQL_KEYWORDS)


def is_formatted_sql(node):
    """
    Detect string formatting using the % operator where the left operand is an
    SQL string (e.g. "SELECT ... %s") and the right operand is a variable.
    """
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Mod):
        if is_sql_string(node.left):
            return True
    return False


def call_is_execute(node):
    """Check if a Call node represents a call to db.engine.execute (or any .execute)."""
    # Direct attribute chain: something.execute(...)
    if isinstance(node.func, ast.Attribute) and node.func.attr == "execute":
        return True
    return False


def find_vuln(tree):
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and call_is_execute(node):
            if node.args:
                arg = node.args[0]
                if is_formatted_sql(arg):
                    return True
    return False


def main():
    try:
        with open(SOURCE_FILE, "r", encoding="utf-8") as f:
            source = f.read()
        tree = ast.parse(source, filename=SOURCE_FILE)
        if find_vuln(tree):
            print("VALIDATION_SUCCESS: Formatted SQL query detected.")
            sys.exit(0)
    except Exception as e:
        print(f"VALIDATION_ERROR: {e}", file=sys.stderr)

    sys.exit(1)


if __name__ == "__main__":
    main()

import sys
import ast

# Target source file
source_file = "/src/app/app.py"

# Collect variable names that are created via unsafe `%` string formatting
unsafe_vars = set()

def is_mod_format(node):
    """Return True if node represents a `%` formatting operation on a string literal."""
    return isinstance(node, ast.BinOp) and isinstance(node.op, ast.Mod) and isinstance(node.left, (ast.Str, ast.Constant))

def collect_unsafe_assignments(tree):
    """Populate unsafe_vars with names assigned using `%` formatting."""
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            if is_mod_format(node.value):
                for target in node.targets:
                    if isinstance(target, ast.Name):
                        unsafe_vars.add(target.id)

def check_render_template_string(tree):
    """Return True if render_template_string is called with an unsafe variable."""
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            # function name could be render_template_string directly or via attribute
            func = node.func
            func_name = ""
            if isinstance(func, ast.Name):
                func_name = func.id
            elif isinstance(func, ast.Attribute):
                func_name = func.attr
            if func_name == "render_template_string":
                if node.args:
                    first_arg = node.args[0]
                    # direct formatted string (e.g., " ... %s" % var)
                    if is_mod_format(first_arg):
                        return True
                    # variable previously marked as unsafe
                    if isinstance(first_arg, ast.Name) and first_arg.id in unsafe_vars:
                        return True
    return False

try:
    with open(source_file, "r", encoding="utf-8") as f:
        tree = ast.parse(f.read(), filename=source_file)
except FileNotFoundError:
    print("VALIDATION_ERROR: Source file not found")
    sys.exit(1)
except Exception as e:
    print(f"VALIDATION_ERROR: {e}")
    sys.exit(1)

collect_unsafe_assignments(tree)

if check_render_template_string(tree):
    print("VALIDATION_SUCCESS: Detected unsafe template string used with render_template_string.")
    sys.exit(0)

sys.exit(1)

import sys
import ast

source_file = "/src/app/app.py"

def is_render_template_string_call(node):
    """Return True if the Call node is render_template_string with a templated string."""
    # Ensure it's a direct call to render_template_string (e.g., not attribute access)
    if isinstance(node, ast.Call):
        func = node.func
        if isinstance(func, ast.Name) and func.id == "render_template_string":
            if not node.args:
                return False
            tmpl_arg = node.args[0]

            # Detect classic %-formatting: "<template>" % var
            if isinstance(tmpl_arg, ast.BinOp) and isinstance(tmpl_arg.op, ast.Mod):
                return True

            # Detect .format() usage: "<template>{}".format(var)
            if isinstance(tmpl_arg, ast.Call) and isinstance(tmpl_arg.func, ast.Attribute):
                if tmpl_arg.func.attr == "format":
                    return True

            # Detect f-strings (JoinedStr)
            if isinstance(tmpl_arg, ast.JoinedStr):
                return True
    return False

def main():
    try:
        with open(source_file, "r", encoding="utf-8") as f:
            tree = ast.parse(f.read(), filename=source_file)
    except Exception as e:
        print(f"VALIDATION_ERROR: Unable to read or parse source file – {e}")
        sys.exit(1)

    for node in ast.walk(tree):
        if is_render_template_string_call(node):
            print("VALIDATION_SUCCESS: render_template_string called with a dynamically formatted template.")
            sys.exit(0)

    sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import ast

source_file = "/src/app/app.py"

class YamlLoadVisitor(ast.NodeVisitor):
    def __init__(self):
        self.vulnerable = False

    def visit_Call(self, node):
        # Detect yaml.load(...)
        if isinstance(node.func, ast.Attribute):
            if (
                isinstance(node.func.value, ast.Name)
                and node.func.value.id == "yaml"
                and node.func.attr == "load"
            ):
                # If a Loader keyword is supplied, consider it safe
                has_loader = any(kw.arg == "Loader" for kw in node.keywords)
                if not has_loader:
                    self.vulnerable = True
        self.generic_visit(node)

try:
    with open(source_file, "r", encoding="utf-8") as f:
        tree = ast.parse(f.read(), filename=source_file)

    visitor = YamlLoadVisitor()
    visitor.visit(tree)

    if visitor.vulnerable:
        print("VALIDATION_SUCCESS: yaml.load used without a safe Loader.")
        sys.exit(0)
except Exception as e:
    print(f"VALIDATION_ERROR: {e}", file=sys.stderr)

sys.exit(1)

import sys, re

source_file = "/src/old-workflows/semgrep.yml"

mutable_found = False
uses_pattern = re.compile(r'^\s*uses:\s*(\S+)', re.IGNORECASE)

def is_mutable_reference(ref: str) -> bool:
    """
    Returns True if the reference after '@' is NOT a full 40‑character SHA.
    """
    if "@" not in ref:
        return False
    tag = ref.rsplit("@", 1)[1]
    return not re.fullmatch(r"[0-9a-fA-F]{40}", tag)

try:
    with open(source_file, "r") as fh:
        for line in fh:
            match = uses_pattern.match(line)
            if match:
                ref = match.group(1).strip()
                if is_mutable_reference(ref):
                    mutable_found = True
                    break
except Exception:
    sys.exit(1)

if mutable_found:
    print("VALIDATION_SUCCESS: Mutable action tag detected.")
    sys.exit(0)
else:
    sys.exit(1)
